CREATE DATABASE IF NOT EXISTS typecad CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE typecad;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(320) NOT NULL UNIQUE,display_name VARCHAR(120) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','designer','viewer') NOT NULL DEFAULT 'designer',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,description TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_projects_owner FOREIGN KEY(owner_user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS drawings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,name VARCHAR(200) NOT NULL,units ENUM('mm','cm','m','in','ft') NOT NULL DEFAULT 'mm',version INT UNSIGNED NOT NULL DEFAULT 1,metadata JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_drawings_project(project_id),CONSTRAINT fk_drawings_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS drawing_layers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,drawing_id BIGINT UNSIGNED NOT NULL,layer_key VARCHAR(100) NOT NULL,name VARCHAR(100) NOT NULL,properties JSON NOT NULL,UNIQUE KEY uq_drawing_layer_name(drawing_id,name),CONSTRAINT fk_layers_drawing FOREIGN KEY(drawing_id) REFERENCES drawings(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS drawing_entities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,drawing_id BIGINT UNSIGNED NOT NULL,entity_key CHAR(36) NOT NULL,entity_type VARCHAR(32) NOT NULL,layer_key VARCHAR(100) NOT NULL,geometry JSON NOT NULL,properties JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_drawing_entity(drawing_id,entity_key),INDEX idx_entities_type(drawing_id,entity_type),CONSTRAINT fk_entities_drawing FOREIGN KEY(drawing_id) REFERENCES drawings(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS drawing_revisions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,drawing_id BIGINT UNSIGNED NOT NULL,author_user_id BIGINT UNSIGNED NULL,revision_number INT UNSIGNED NOT NULL,message VARCHAR(500) NOT NULL,snapshot JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_drawing_revision(drawing_id,revision_number),CONSTRAINT fk_revisions_drawing FOREIGN KEY(drawing_id) REFERENCES drawings(id) ON DELETE CASCADE,CONSTRAINT fk_revisions_author FOREIGN KEY(author_user_id) REFERENCES users(id) ON DELETE SET NULL);